head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf90700";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf90700.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "a_62", attr: "src", fn: function () { return "http://" + String(dma_map.get("hpage")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_corpRegNoP_txt", fn: function(){ return ((dma_map.get("corpRegNoP") ?? (() => { throw new Error("unresolved:" + "map.corpRegNoP"); })()) !== '-'); } }, { id: "if_bzRegNoP_txt", fn: function(){ return ((dma_map.get("bzRegNoP") ?? (() => { throw new Error("unresolved:" + "map.bzRegNoP"); })()) !== '--'); } }, { id: "if_cntrCd_txt", fn: function(){ return ((dma_map.get("cntrCd") ?? (() => { throw new Error("unresolved:" + "map.cntrCd"); })()) === '410'); } }, { id: "if_acntclsMmdd1_txt", fn: function(){ return ((dma_map.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd1"); })()) !== ''); } }, { id: "if_acntclsMmdd2_txt", fn: function(){ return ((dma_map.get("acntclsMmdd2") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd2"); })()) !== ''); } }, { id: "if_acntclsMmdd3_txt", fn: function(){ return ((dma_map.get("acntclsMmdd3") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd3"); })()) !== ''); } }, { id: "if_acntclsMmdd4_txt", fn: function(){ return ((dma_map.get("acntclsMmdd4") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd4"); })()) !== ''); } }, { id: "if_acntclsMmdd5_txt", fn: function(){ return ((dma_map.get("acntclsMmdd5") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd5"); })()) !== ''); } }, { id: "if_acntclsMmdd6_txt", fn: function(){ return ((dma_map.get("acntclsMmdd6") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd6"); })()) !== ''); } }, { id: "if_acntclsMmdd7_txt", fn: function(){ return ((dma_map.get("acntclsMmdd7") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd7"); })()) !== ''); } }, { id: "if_acntclsMmdd8_txt", fn: function(){ return ((dma_map.get("acntclsMmdd8") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd8"); })()) !== ''); } }, { id: "if_acntclsMmdd9_txt", fn: function(){ return ((dma_map.get("acntclsMmdd9") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd9"); })()) !== ''); } }, { id: "if_acntclsMmdd10_txt", fn: function(){ return ((dma_map.get("acntclsMmdd10") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd10"); })()) !== ''); } }, { id: "if_acntclsMmdd11_txt", fn: function(){ return ((dma_map.get("acntclsMmdd11") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd11"); })()) !== ''); } }, { id: "if_acntclsMmdd12_txt", fn: function(){ return ((dma_map.get("acntclsMmdd12") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd12"); })()) !== ''); } }, { id: "if_bfsplitComNm", fn: function(){ return ((dma_map.get("bfsplitComNm") ?? (() => { throw new Error("unresolved:" + "map.bfsplitComNm"); })()) !== ''); } }, { id: "tr_106", fn: function(){ return ((dma_map.get("bfsplitComNm") ?? (() => { throw new Error("unresolved:" + "map.bfsplitComNm"); })()) !== ''); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "btn_openCorpModList", fn: function () { return String(dma_map.get("comNm")); } },
        { childId: "__rb11", fn: function () { return "[" + String(dma_map.get("zipcd1")) + "-" + String(dma_map.get("zipcd2")) + "]"; } },
        { childId: "__rb12", fn: function () { return String(dma_map.get("addr")) + " " + String(dma_map.get("dtlAddr")); } },
        { childId: "__rb13", fn: function () { return String(dma_map.get("engAddr")) + " " + String(dma_map.get("engDtlAddr")); } },
        { childId: "a_62", fn: function () { return String(dma_map.get("hpage")); } },
        { childId: "__rb17", fn: function () { return String(dma_map.get("acntclsMmdd1")) + "월"; } },
        { childId: "__rb18", fn: function () { return ", " + String(dma_map.get("acntclsMmdd2")) + "월"; } },
        { childId: "__rb19", fn: function () { return ", " + String(dma_map.get("acntclsMmdd3")) + "월"; } },
        { childId: "__rb20", fn: function () { return ", " + String(dma_map.get("acntclsMmdd4")) + "월"; } },
        { childId: "__rb21", fn: function () { return ", " + String(dma_map.get("acntclsMmdd5")) + "월"; } },
        { childId: "__rb22", fn: function () { return ", " + String(dma_map.get("acntclsMmdd6")) + "월"; } },
        { childId: "__rb23", fn: function () { return ", " + String(dma_map.get("acntclsMmdd7")) + "월"; } },
        { childId: "__rb24", fn: function () { return ", " + String(dma_map.get("acntclsMmdd8")) + "월"; } },
        { childId: "__rb25", fn: function () { return ", " + String(dma_map.get("acntclsMmdd9")) + "월"; } },
        { childId: "__rb26", fn: function () { return ", " + String(dma_map.get("acntclsMmdd10")) + "월"; } },
        { childId: "__rb27", fn: function () { return ", " + String(dma_map.get("acntclsMmdd11")) + "월"; } },
        { childId: "__rb28", fn: function () { return ", " + String(dma_map.get("acntclsMmdd12")) + "월"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_openCorpModList_onclick
 * @description btn_openCorpModList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_openCorpModList_onclick = async function(e){
    try {
        await scwin.open_corpModList('' + dma_map.get("isurCd") + '','' + dma_map.get("comNm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90700.btn_openCorpModList_onclick' }); }
};

/**
 * @method
 * @name btn_closeWin_onclick
 * @description btn_closeWin 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_closeWin_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90700.btn_closeWin_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_open_corpModList
 * @description open corp Mod List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_open_corpModList = async function () {
    const sbmOptions = {
        id: "tx_open_corpModList",
        method: "post",
        action: "/common/corp.do?method=corpModList",
        ref: "dma_openCorpModListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name open_modify
 * @description open modify 처리
 * @returns {void}
 * @hidden N
 */
scwin.open_modify = function () {
    const form = (document.JLDINF90700 || { elements: [] });
    fn_popupCorpUpdReq(form);
    $c.win.closePopup();
};

/**
 * @method
 * @name open_corpModList
 * @description open corp Mod List 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {String} ipt_comNm ipt_comNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.open_corpModList = async function (ipt_isurCd, ipt_comNm) {
    const fm = JLDINF90700;
    fm.isur_cd.value = ipt_isurCd;
    fm.com_nm.value = ipt_comNm;
    let _popupWindow;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _popupWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/common/corp.do?method=corpModList", unresolved: "nav:" + "/common/corp.do?method=corpModList" }; })();
    fm.action = '/common/corp.do?method=corpModList';

};
